window.FILM_WORK_PROMPTS={"work_id":"src-835f8335e0ed6276","records":[{"work_id":"src-835f8335e0ed6276","frame_id":"FG-f0e08192b14f997f","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Evolution007.jpg","source_page":"https://film-grab.com/2019/08/30/evolution/","scene":"一名赤膊穿红短裤的人物在灰白破败建筑群间的黑色碎石路面上奔跑，周围是斑驳的混凝土墙体与门窗。","analysis":"人物位于画面中央偏左，全身可见，呈奔跑姿态，身形在广阔环境中显得较小。建筑占据画面左右两侧及背景，形成狭窄通道。光线为阴天漫射光，整体色调偏冷灰，墙面有剥落痕迹，地面为深色碎石，明暗对比平缓。","prompt":"一名赤膊穿红短裤的人物在灰白破败建筑群间的黑色碎石路面上奔跑，人物全身可见，身形较小，位于画面中央偏左。周围是斑驳的混凝土墙体，墙面有剥落痕迹，门窗呈深色矩形。建筑占据画面左右两侧及背景，形成狭窄通道。光线为阴天漫射光，整体色调偏冷灰，地面为深色碎石，明暗对比平缓，无强烈阴影。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-08T02:50:16-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Evolution007.jpg","observed_dimensions":[1280,537],"source_thumbnail_dimensions":[500,210],"source_image_match_mae":0.533,"observed_resolution":"normal","observation_limits":[],"id":"VP-8671fe9fc56acb39","origin":"visual"},{"work_id":"src-835f8335e0ed6276","frame_id":"FG-58569352caac59ff","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Evolution020.jpg","source_page":"https://film-grab.com/2019/08/30/evolution/","scene":"黑暗环境中，一名人物站立，双手在胸前持握并展开一件浅色衣物，背景完全漆黑，仅人物与衣物被照亮。","analysis":"人物位于画面中央，头部至大腿中部可见，背景为纯黑。光线从上方或前方投射，照亮面部、双手及衣物，形成强烈的明暗对比。衣物呈黄绿色调，褶皱丰富，占据画面中心较大面积。人物面部表情平静，眼神直视前方，整体氛围神秘而压抑。","prompt":"在完全漆黑的背景中，一名人物站立于画面中央，仅上半身及大腿部分可见。人物双手在胸前持握并展开一件浅色衣物，衣物呈黄绿色调，褶皱丰富，占据画面中心较大面积。光线从上方或前方投射，照亮人物面部、双手及衣物，形成强烈的明暗对比。人物面部表情平静，眼神直视前方，整体氛围神秘而压抑。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-08T02:50:16-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Evolution020.jpg","observed_dimensions":[1280,537],"source_thumbnail_dimensions":[500,210],"source_image_match_mae":0.585,"observed_resolution":"normal","observation_limits":[],"id":"VP-3df57c0c4e4da6c8","origin":"visual"},{"work_id":"src-835f8335e0ed6276","frame_id":"FG-f4f8367a3badeb56","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Evolution033.jpg","source_page":"https://film-grab.com/2019/08/30/evolution/","scene":"极近距离的人眼特写，占据画面绝大部分。深绿色调笼罩，瞳孔中反射出明亮的黄绿色光点，周围皮肤与睫毛隐没在阴影中。","analysis":"画面主体为一只睁开的眼睛，占据画面中心及右侧区域。上方可见浓密的眉毛与几缕散乱的发丝，下方隐约可见下睫毛。瞳孔中心有一个清晰的黄绿色高光反射，呈十字星芒状。整体光线极暗，采用侧光或底光照明，仅照亮眼部轮廓与皮肤局部，其余部分沉入黑暗。色彩以深绿、暗褐为主，明暗对比强烈，营造出神秘、压抑的视觉氛围。","prompt":"极近距离的人眼特写，画面被深沉的暗绿色调笼罩。一只眼睛占据画面中心，瞳孔深邃，中心反射出一个明亮的黄绿色光点，光点呈现十字星芒状。上方是浓密的黑色眉毛和几缕散乱的发丝，下方隐约可见下睫毛的轮廓。皮肤在微弱的光线下呈现出暗褐色调，大部分区域隐没在阴影中。光线从侧面或下方投射，仅照亮眼部局部，形成强烈的明暗对比。整体氛围神秘、压抑，色彩层次丰富，以深绿和暗褐为主，细节模糊，充满电影质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-08T02:50:16-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Evolution033.jpg","observed_dimensions":[1280,537],"source_thumbnail_dimensions":[500,210],"source_image_match_mae":0.481,"observed_resolution":"normal","observation_limits":[],"id":"VP-3ea312da6b0142ea","origin":"visual"},{"work_id":"src-835f8335e0ed6276","frame_id":"FG-c7fb8fd582b41e7d","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Evolution046.jpg","source_page":"https://film-grab.com/2019/08/30/evolution/","scene":"昏暗破败的室内，一名戴白色头巾的人物坐在铺着深红色被褥的床铺上，左侧立有输液架，右侧有一扇半开的门。","analysis":"画面采用暗调处理，大面积黑色阴影占据左侧与背景，营造出压抑氛围。人物位于画面中右侧，呈坐姿，上半身及腿部可见，头部微低。左侧输液架上的透明袋体在微弱光线下反光，右侧门框形成垂直亮线。整体光色偏冷绿，光线微弱，仅照亮人物轮廓及床铺局部，明暗对比强烈。","prompt":"昏暗破败的室内场景，整体色调呈阴冷的暗绿色，大面积黑色阴影笼罩。画面中右侧，一名戴白色头巾、身穿浅色短袖上衣的人物坐在床铺上，姿态低沉，床铺上铺着深红色褶皱被褥。人物左侧立着一个金属输液架，挂着两个透明输液袋。右侧背景有一扇半开的门，门框边缘有微弱亮光。环境显得陈旧压抑，光线极暗，仅微弱地照亮人物轮廓和床铺局部，营造出一种孤寂、阴森的视觉感受。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-08T02:50:16-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Evolution046.jpg","observed_dimensions":[1280,537],"source_thumbnail_dimensions":[500,210],"source_image_match_mae":0.493,"observed_resolution":"normal","observation_limits":[],"id":"VP-84dcf935d01bbd5a","origin":"visual"},{"work_id":"src-835f8335e0ed6276","frame_id":"FG-a511b1980839af46","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Evolution059.jpg","source_page":"https://film-grab.com/2019/08/30/evolution/","scene":"一艘锈迹斑斑的白色小船漂浮在灰暗平静的海面上，船头竖立着一盏金属灯。船舱内，一名长发女子身穿粉色衣物蜷缩坐着，前景处可见另一人背部及白色内裤，整体氛围阴郁压抑。","analysis":"画面采用船头向内的视角，船体边缘形成V字形引导线。女子位于画面中右侧，呈蜷缩坐姿，长发垂落遮挡部分面部；前景人物仅露出背部和臀部，占据画面下方。整体光线昏暗，天空与海面呈现低饱和度的灰蓝色调，船体白色油漆剥落露出锈迹，色彩层次单一且冷峻。","prompt":"一艘老旧的白色小船漂浮在灰暗平静的海面上，天空阴沉，光线昏暗。船体油漆剥落，露出明显的锈迹，船头中央竖立着一盏金属灯。船舱内，一名长发女子身穿粉色衣物，蜷缩着坐在右侧，长发垂落。前景处可见另一人的背部和白色内裤，身体横卧。整体色调为低饱和度的灰蓝色，氛围阴郁压抑，构图以船体边缘为引导线，人物处于封闭空间内。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-08T02:50:16-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Evolution059.jpg","observed_dimensions":[1280,537],"source_thumbnail_dimensions":[500,210],"source_image_match_mae":0.5,"observed_resolution":"normal","observation_limits":[],"id":"VP-0a694f9f5189a2e3","origin":"visual"},{"work_id":"src-835f8335e0ed6276","frame_id":"FG-0ee3af9a6a258ef9","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Evolution008.jpg","source_page":"https://film-grab.com/2019/08/30/evolution/","scene":"昏暗厨房内，一名穿灰裙女子与一名赤膊红短裤男孩面对面站立，背景可见白色炉灶、锅具及右侧餐桌椅。","analysis":"画面采用平视视角，构图将人物置于中央偏左，右侧大面积暗部形成视觉平衡。女子全身可见，男孩全身可见，两人高度差明显。光线从左侧射入，在人物面部和身体一侧形成高光，另一侧陷入阴影，整体色调偏冷绿，明暗对比强烈，营造出压抑、静谧的氛围。","prompt":"昏暗的室内厨房场景，冷绿色调。画面中央，一名扎马尾、身穿灰褐色连衣裙的女子侧身站立，面向右侧，手中似乎拿着深色衣物。她对面站着一名赤裸上身、穿红色短裤的男孩，两人面对面，距离较近。背景是一台白色老式炉灶，上面放着金属锅，墙面斑驳。画面右侧前景是模糊的深色餐桌和椅背，占据约三分之一画面，形成前景遮挡。光线从左侧窗户射入，照亮人物轮廓，室内大部分区域处于阴影中，氛围压抑。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T20:04:58+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Evolution008.jpg","observed_dimensions":[1280,537],"source_thumbnail_dimensions":[500,210],"source_image_match_mae":0.499,"observed_resolution":"normal","observation_limits":[],"id":"VP-97af7a365887e5ae","origin":"visual"},{"work_id":"src-835f8335e0ed6276","frame_id":"FG-dae7b9738bf4135f","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Evolution021.jpg","source_page":"https://film-grab.com/2019/08/30/evolution/","scene":"人物面部占据画面主体，背景为纯黑。人物头部微低，视线向下，面部皮肤在黄绿色光照下显得湿润，脸颊处可见明显的泪痕或汗液反光。","analysis":"画面采用极近距离构图，仅展示人物面部及耳部，背景完全隐没于黑暗。光线从上方投射，呈现强烈的黄绿色调，照亮额头、鼻梁及面颊，形成高对比度的明暗层次。人物面部皮肤纹理清晰，额头与脸颊布满细密的水珠或汗液，在光线下闪烁。人物视线向下，神情凝重，面部占据画面约80%面积。","prompt":"极近距离的人物面部特写，背景为纯黑。人物头部微低，视线向下，神情凝重。面部皮肤在强烈的黄绿色光照下显得湿润，额头、鼻梁及脸颊布满细密的水珠或汗液，在光线下闪烁。脸颊处可见明显的泪痕或汗液反光。光线从上方投射，形成高对比度的明暗层次，照亮面部轮廓，其余部分隐没在黑暗中。画面色调偏黄绿，质感真实，皮肤纹理清晰可见。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T20:05:05+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Evolution021.jpg","observed_dimensions":[1280,537],"source_thumbnail_dimensions":[500,210],"source_image_match_mae":0.531,"observed_resolution":"normal","observation_limits":[],"id":"VP-726efc8f5eb22858","origin":"visual"},{"work_id":"src-835f8335e0ed6276","frame_id":"FG-5f042ca94dbaa09a","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Evolution034.jpg","source_page":"https://film-grab.com/2019/08/30/evolution/","scene":"昏暗室内，左侧可见人物上半身剪影，背景为倾斜的淡黄色墙面，右侧大面积黑暗。","analysis":"构图极度不对称，主体位于左上角，右侧约70%为纯黑。人物仅见头部与肩部轮廓，呈剪影状。背景墙面呈倾斜角度，色调为暗黄，光线微弱且集中在墙面上，形成强烈的明暗对比，营造出压抑、神秘的视觉氛围。","prompt":"极度昏暗的室内场景，画面左侧偏上位置有一个模糊的人物上半身剪影，头部轮廓清晰但面部不可见。人物背后是一面倾斜的淡黄色墙壁，墙面质感粗糙，光线微弱地照亮了墙壁的一角。画面右侧及下方约70%的区域完全被浓重的黑色阴影覆盖，形成大面积的负空间。整体色调以深黑和暗黄为主，光影对比强烈，营造出一种压抑、静谧且充满未知的视觉感受。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T20:05:11+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Evolution034.jpg","observed_dimensions":[1280,537],"source_thumbnail_dimensions":[500,210],"source_image_match_mae":0.194,"observed_resolution":"normal","observation_limits":[],"id":"VP-a3d60b7bbf358ddd","origin":"visual"},{"work_id":"src-835f8335e0ed6276","frame_id":"FG-d6c459939e8477dd","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Evolution047.jpg","source_page":"https://film-grab.com/2019/08/30/evolution/","scene":"昏暗走廊中，一名白衣人物站立在金属推车后方，推车上躺着一名人物，背景深处有一扇透着微光的门。","analysis":"画面采用左侧布光，大面积黑暗占据右侧空间。前景人物全身可见，站立姿态，推车上人物呈躺卧状。左上方有一盏长条形灯具发出冷白光，照亮人物面部和白色衣物，与周围深绿色墙壁形成强烈明暗对比。远处门洞内的暖色光点增加了空间纵深感。","prompt":"昏暗的深绿色走廊，左侧墙壁上方安装着一盏长条形荧光灯，发出冷白色光芒。一名身穿白色短袖制服的人物站立在金属推车后方，双手扶着推车边缘，面部被灯光照亮。推车上躺着一名人物，身穿浅色衣物，头部朝向左侧。走廊向深处延伸，尽头有一扇透着暖黄色微光的门洞。右侧大面积处于阴影中，地面呈现暗色反光，整体氛围阴郁压抑，明暗对比强烈。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T20:05:18+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Evolution047.jpg","observed_dimensions":[1280,537],"source_thumbnail_dimensions":[500,210],"source_image_match_mae":0.525,"observed_resolution":"normal","observation_limits":[],"id":"VP-70dc58fd8a7efebf","origin":"visual"},{"work_id":"src-835f8335e0ed6276","frame_id":"FG-1caede014359d1f5","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Evolution060.jpg","source_page":"https://film-grab.com/2019/08/30/evolution/","scene":"画面主体为一名年轻女性的面部特写，她留着湿润的深褐色卷发，神情平静地直视前方。背景是模糊的灰蓝色海面与天空，环境占据画面边缘，整体色调阴冷。","analysis":"构图采用中心对称，人物面部占据画面约60%的宽度，仅可见头部及颈部上方。镜头视角平视，焦点清晰地落在双眼与鼻梁上，背景完全虚化。光线为柔和的漫射光，无强烈阴影，色彩以低饱和度的青灰色和深褐色为主，营造出一种沉静、压抑的视觉氛围。","prompt":"一名年轻女性的面部特写，她拥有湿润的深褐色卷发，发丝凌乱地垂在脸颊两侧，部分发梢贴在皮肤上。她的眼神平静而深邃，直视镜头，面部皮肤质感真实，带有自然的肤色纹理。背景是极度虚化的灰蓝色海面与天空，水平线模糊不清，营造出一种阴冷、潮湿的环境氛围。光线柔和且均匀，没有明显的强光源或阴影，整体色调偏向低饱和度的青灰色，呈现出一种沉静、忧郁的视觉风格。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T20:05:25+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Evolution060.jpg","observed_dimensions":[1280,537],"source_thumbnail_dimensions":[500,210],"source_image_match_mae":0.517,"observed_resolution":"normal","observation_limits":[],"id":"VP-a50553f50c83443f","origin":"visual"}]};